mapper.update:
UPDATE favorite_tags 
SET use_count = use_count + 1, update_time = NOW()
WHERE id = #{id}

UPDATE favorite_tags 
SET use_count = GREATEST(use_count - 1, 0), update_time = NOW()
WHERE id = #{id}

